components.css:
.ds-film-caption { margin-top: 12px; }
  .ds-film-transcript summary { width: fit-content; cursor: pointer; padding: 8px 0; font-size: 14px; color: var(--muted); }
  .ds-film-transcript summary:hover { color: var(--ink); }
  .ds-film-transcript-body { max-width: 70ch; margin: 12px auto 28px; padding: 24px; background: var(--soft); font-size: 17px; line-height: 1.65; }
  .ds-film-transcript-body h3 { font-size: 24px; margin: 28px 0 12px; }
  .ds-film-transcript-body p + p { margin-top: 14px; }
  .ds-film-transcript-body blockquote { margin: 16px 0; padding: 16px; background: var(--surface); }
  .ds-film-transcript-body code { font-size: .85em; overflow-wrap: anywhere; }
  .ds-film-transcript-body a { text-decoration: underline; overflow-wrap: anywhere; }
  @media (max-width: 550px) { .ds-film-caption { padding-inline: 10px; } .ds-film-transcript-body { padding: 18px; } }.ds-film{margin:0;color:var(--ink,#18191d);font:400 17px/1.55 var(--font,Jost,Arial,sans-serif)}.ds-film-frame{aspect-ratio:16/9;background:var(--ink,#18191d);border-radius:16px;overflow:hidden}.ds-film-video{display:block;width:100%;height:100%;object-fit:cover}.ds-film summary:focus-visible,.ds-film a:focus-visible{outline:3px solid var(--accent-ink,#b52e10);outline-offset:5px}.ds-film-transcript-body code{font-family:var(--mono,monospace)}@media(max-width:800px){.ds-film-frame{border-radius:12px}}@media(max-width:550px){.ds-film-frame{border-radius:8px}}
